() => {
  const heading = Array.from(document.querySelectorAll('h1,h2,h3')).map(el => el.innerText.trim()).filter(Boolean);
  const rows = Array.from(document.querySelectorAll('[role="row"]'));
  const testers = rows.map(row => {
    const text = (row.innerText || '').replace(/\s+/g, ' ').trim();
    return text;
  }).filter(t => t && !t.includes('测试员') || t.includes('@') || /[一-鿿]/.test(t));
  const body = document.body.innerText || '';
  return {
    url: location.href,
    headings: heading.slice(0, 20),
    rowCount: rows.length,
    hasPengYan: body.includes('彭燕'),
    hasEmail: body.includes('cham2015@126.com'),
    hasIpad: body.includes('iPad Air'),
    hasIos: body.includes('18.7.8'),
    testers
  };
}

() => {
  const grid = document.querySelector('[role="grid"]');
  if (!grid) return { error: 'no grid' };
  const scrollParents = [];
  let el = grid;
  while (el) {
    const style = getComputedStyle(el);
    const overflow = style.overflow + style.overflowY + style.overflowX;
    if ((el.scrollHeight > el.clientHeight + 20) || overflow.includes('auto') || overflow.includes('scroll')) {
      scrollParents.push({
        tag: el.tagName,
        className: String(el.className).slice(0, 120),
        scrollTop: el.scrollTop,
        scrollHeight: el.scrollHeight,
        clientHeight: el.clientHeight
      });
    }
    el = el.parentElement;
  }
  return {
    gridScroll: { scrollTop: grid.scrollTop, scrollHeight: grid.scrollHeight, clientHeight: grid.clientHeight },
    scrollParents,
    filterButtons: Array.from(document.querySelectorAll('button')).map(b => b.innerText.trim()).filter(t => t).slice(0, 40)
  };
}

async () => {
  const url = 'https://appstoreconnect.apple.com/iris/v1/apps/6544800416/metrics/betaTesterUsages?include=betaTesters&sort=betaTesters.state&groupBy=betaTesters';
  const res = await fetch(url, { credentials: 'include' });
  const json = await res.json();
  const testers = (json.included || json.data || []).filter(x => x.type === 'betaTesters' || (x.attributes && (x.attributes.email || x.attributes.firstName)));
  const included = json.included || [];
  const data = json.data || [];
  const fromIncluded = included.filter(x => x.type === 'betaTesters').map(t => ({
    email: t.attributes && t.attributes.email,
    firstName: t.attributes && t.attributes.firstName,
    lastName: t.attributes && t.attributes.lastName,
    inviteType: t.attributes && t.attributes.inviteType,
    state: t.attributes && t.attributes.state
  }));
  const fromData = data.filter(x => x.type === 'betaTesters').map(t => ({
    email: t.attributes && t.attributes.email,
    firstName: t.attributes && t.attributes.firstName,
    lastName: t.attributes && t.attributes.lastName
  }));
  const all = fromIncluded.length ? fromIncluded : fromData;
  const emails = all.map(t => t.email).filter(Boolean);
  return {
    status: res.status,
    types: Array.from(new Set([...(included.map(i=>i.type)), ...(data.map(i=>i.type))])),
    testerCount: all.length,
    emails,
    names: all.map(t => ((t.firstName||'') + ' ' + (t.lastName||'')).trim()),
    hasPengYan: JSON.stringify(json).includes('彭燕'),
    hasEmail: JSON.stringify(json).includes('cham2015@126.com'),
    hasIpad: JSON.stringify(json).includes('iPad Air')
  };
}

